node --input-type=module <<'NODE'
import fs from 'node:fs';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
const rows = JSON.parse(fs.readFileSync('docs/remediation/evidence/W05.08/before-sources-v1.json', 'utf8'));
const expected = ['src/routes/realtime.ts', 'src/services/RealtimeSegmentEngine.ts', 'src/services/SessionManager.ts', 'src/durable-objects/ShopperReflex.ts', 'src/routes/realtime.sdkContract.test.ts'];
if (JSON.stringify(rows.map(r => r.path).sort()) !== JSON.stringify([...expected].sort())) throw new Error('Unexpected baseline scope');
const sha = v => crypto.createHash('sha256').update(v).digest('hex');
const pins = [];
for (const r of rows) {
  if (sha(r.contents) !== r.sha256) throw new Error('Baseline identity mismatch: ' + r.path);
  const now = fs.readFileSync(r.path, 'utf8');
  pins.push({ path: r.path, before: r.sha256, after: sha(now), beforeBytes: Buffer.byteLength(r.contents), afterBytes: Buffer.byteLength(now) });
  const diff = spawnSync('diff', ['-u', '--label', r.path + ' (before W05.08)', '--label', r.path + ' (candidate)', '-', r.path], { input: r.contents, encoding: 'utf8', maxBuffer: 4 * 1024 * 1024 });
  process.stdout.write(diff.stdout); process.stderr.write(diff.stderr);
  if (diff.error || diff.status > 1 || diff.status === null) throw diff.error ?? new Error('Scoped diff failed');
}
const whitespace = spawnSync('git', ['diff', '--check', '--', ...expected], { encoding: 'utf8' });
process.stdout.write(whitespace.stdout); process.stderr.write(whitespace.stderr);
if (whitespace.status !== 0) throw new Error('Scoped whitespace check failed');
console.log('SCOPED_PINS ' + JSON.stringify(pins));
console.log('SCOPED_DIFF_PASS: five declared source/fixture files; retained pre-task originals verified; git diff --check passed. Unrelated dirty files are not attributed to this task.');
NODE
